-- 2026-11-14 (~2:15 PM PT, Cowork cloud; Trevor upgraded Dune to Analyst so the query could run).
-- Archive of every Flowty loan DEFAULT (FundingSettled: the NFT went to the lender) whose lender is a
-- wallet RPC tracks, with the original principal from the loan's ListingAvailable event.
-- Source: Dune query 9128523 (private), execution 01M7E1RP0HC7T188NG7PEAH8CB — 3,065 lifetime defaults
-- (2022-01 → 2026-06), filtered by lender to the 461 tracked-address spellings (Dune drops leading zeros
-- after 0x on older events, so both spellings were matched) → 219 rows, 5 lenders, $17,988.63.
-- Positive control: the 8 loans RPC's own index already had (2025-12-29 onward) match to the cent.
-- The one FlowToken-denominated loan is kept here but NOT used for cost (FLOW is not 1:1 with USD).
-- Revert: DROP TABLE flowty_archive.loan_defaults_dune_20261114;
CREATE TABLE IF NOT EXISTS flowty_archive.loan_defaults_dune_20261114 (nft_id text NOT NULL, collection text NOT NULL, principal numeric NOT NULL, payment_token text NOT NULL, settled_block bigint NOT NULL, lender text NOT NULL, PRIMARY KEY (lender, nft_id, collection, settled_block));
COMMENT ON TABLE flowty_archive.loan_defaults_dune_20261114 IS 'Flowty FundingSettled (loan defaulted to lender) joined to ListingAvailable principal, from Dune query 9128523 execution 01M7E1RP0HC7T188NG7PEAH8CB (2026-11-14), filtered to lenders present in wallet_moments_cache. Source for loan_default cost basis of pre-index (before 2025-12-29) Flowty loans.';
